// package dict contains dictionaries for finding scientific names
package dict

import (
	_ "embed"

	"github.com/gnames/gnfinder/pkg/io/dict/hashdict"
)

// All dictionaries are combined into one hash dictionary (see hashdict).
// It is generated by gndict (github.com/gnames/gndict) and copied here
// from gndict's output as data/hashdict/dict.bin.
//
//go:embed data/hashdict/dict.bin
var hashDictData []byte

// DictionaryType describes available dictionaries
type DictionaryType int

func (d DictionaryType) String() string {
	types := [...]string{"notSet", "inGenus", "inAmbigGenus", "inAmbigGenusSp",
		"inUninomial", "inAmbigUninomial", "notInUninomial", "inSpecies",
		"inAmbigSpecies", "notInSpecies", "commonWords", "rank", "notInDictionary"}
	return types[d]
}

// DictionaryType dictionaries
const (
	NotSet DictionaryType = iota
	InGenus
	InAmbigGenus
	InAmbigGenusSp
	InUninomial
	InAmbigUninomial
	NotInUninomial
	InSpecies
	InAmbigSpecies
	NotInSpecies
	CommonWords
	Rank
	NotInDictionary
)

// Dictionary contains dictionaries used for detecting scientific names.
//
// All sets except Ranks are views of one hash dictionary. Lookup returns
// all dictionaries of a word at once, and is the fast way to check several
// of them. A word that is not in a dictionary is reported as present only
// if its 64-bit hash equals the hash of a dictionary word, which is very
// unlikely.
type Dictionary struct {
	NotInUninomials   Set
	NotInSpecies      Set
	CommonWords       Set
	InAmbigGenera     Set
	InAmbigGeneraSp   Set
	InAmbigSpecies    Set
	InAmbigUninomials Set
	InGenera          Set
	InSpecies         Set
	InUninomials      Set
	Ranks             Set

	hd *hashdict.Dict
}

// LoadDictionary contain most popular words in European languages.
func LoadDictionary() (*Dictionary, error) {
	hd, err := hashdict.Load(hashDictData)
	if err != nil {
		return nil, err
	}
	set := func(f hashdict.Flags) Set { return flagSet{hd, f} }
	d := &Dictionary{
		NotInUninomials:   set(hashdict.NotInUninomial),
		NotInSpecies:      set(hashdict.NotInSpecies),
		CommonWords:       set(hashdict.CommonWord),
		InAmbigGenera:     set(hashdict.InAmbigGenus),
		InAmbigGeneraSp:   set(hashdict.InAmbigGenusSp),
		InAmbigSpecies:    set(hashdict.InAmbigSpecies),
		InAmbigUninomials: set(hashdict.InAmbigUninomial),
		InGenera:          set(hashdict.InGenus),
		InSpecies:         set(hashdict.InSpecies),
		InUninomials:      set(hashdict.InUninomial),
		Ranks:             setRanks(),
		hd:                hd,
	}
	return d, nil
}

// Lookup returns flags of all dictionaries that contain the word.
func (d *Dictionary) Lookup(word string) hashdict.Flags {
	return d.hd.Lookup(word)
}

func setRanks() WordSet {
	var empty struct{}
	ranks := WordSet{
		"nat": empty, "f.sp": empty, "mut.": empty, "morph.": empty,
		"nothosubsp.": empty, "convar.": empty, "pseudovar": empty, "sect.": empty,
		"ser.": empty, "subvar.": empty, "subf.": empty, "race": empty,
		"α": empty, "ββ": empty, "β": empty, "γ": empty, "δ": empty, "ε": empty,
		"φ": empty, "θ": empty, "μ": empty, "a.": empty, "b.": empty,
		"c.": empty, "d.": empty, "e.": empty, "g.": empty, "k.": empty,
		"pv.": empty, "pathovar.": empty, "ab.": empty, "st.": empty, "fm.": empty,
		"variety": empty, "var": empty, "var.": empty, "forma": empty, "fm": empty,
		"forma.": empty, "fma": empty, "fma.": empty, "form": empty, "form.": empty,
		"fo": empty, "fo.": empty, "f": empty, "f.": empty, "ssp": empty,
		"ssp.": empty, "subsp": empty, "subsp.": empty,
	}
	return ranks
}
